#!/usr/bin/env bash
# Termicolor for GNOME Terminal - generated by https://github.com/repraze/termicolor
#
# Usage: ./install.sh [dark|light|both] [--default]
#   --default also makes the profile GNOME Terminal's default (the first one, with "both").
set -euo pipefail

LIST=org.gnome.Terminal.ProfilesList
PROFILE=org.gnome.Terminal.Legacy.Profile

# Registers a profile id in the profile list and prints its gsettings schema:path.
add_profile() {
    local uuid=$1 list
    list=$(gsettings get "$LIST" list)
    if [[ $list != *"'$uuid'"* ]]; then
        if [[ $list == "@as []" || $list == "[]" ]]; then
            list="['$uuid']"
        else
            list="${list%]}, '$uuid']"
        fi
        gsettings set "$LIST" list "$list"
    fi
    echo "$PROFILE:/org/gnome/terminal/legacy/profiles:/:$uuid/"
}

install_dark() {
    local path
    path=$(add_profile 46edc057-d8e6-4aa1-a6a2-3b83272ead24)
    gsettings set "$path" visible-name "'Termicolor Dark'"
    gsettings set "$path" use-theme-colors "false"
    gsettings set "$path" foreground-color "'#fafafa'"
    gsettings set "$path" background-color "'#171717'"
    gsettings set "$path" palette "['#404040', '#ff4c82', '#35e0a3', '#f2c224', '#4d91ff', '#bb7aff', '#2edfeb', '#d4d4d4', '#737373', '#ff7a9a', '#52f4b6', '#ffd86a', '#6fa6ff', '#c898ff', '#4ff3ff', '#ffffff']"
    gsettings set "$path" bold-color-same-as-fg "true"
    gsettings set "$path" bold-color "'#fafafa'"
    gsettings set "$path" cursor-colors-set "true"
    gsettings set "$path" cursor-background-color "'#ff4c82'"
    gsettings set "$path" cursor-foreground-color "'#250e13'"
    gsettings set "$path" highlight-colors-set "true"
    gsettings set "$path" highlight-background-color "'#562b34'"
    gsettings set "$path" highlight-foreground-color "'#fafafa'"
    echo "Installed Termicolor Dark"
}

install_light() {
    local path
    path=$(add_profile 5c7f0537-5c7f-4f86-8e09-fadd0a973257)
    gsettings set "$path" visible-name "'Termicolor Light'"
    gsettings set "$path" use-theme-colors "false"
    gsettings set "$path" foreground-color "'#0a0a0a'"
    gsettings set "$path" background-color "'#ffffff'"
    gsettings set "$path" palette "['#262626', '#e20064', '#00835c', '#a16500', '#006af6', '#a331fb', '#007f87', '#a3a3a3', '#525252', '#fc3378', '#2c9870', '#b77a27', '#3885ff', '#b262ff', '#2c949c', '#d4d4d4']"
    gsettings set "$path" bold-color-same-as-fg "true"
    gsettings set "$path" bold-color "'#0a0a0a'"
    gsettings set "$path" cursor-colors-set "true"
    gsettings set "$path" cursor-background-color "'#e20064'"
    gsettings set "$path" cursor-foreground-color "'#ffffff'"
    gsettings set "$path" highlight-colors-set "true"
    gsettings set "$path" highlight-background-color "'#ffc3ce'"
    gsettings set "$path" highlight-foreground-color "'#0a0a0a'"
    echo "Installed Termicolor Light"
}

which=${1:-both}
default=${2:-}
if [[ $which == "--default" ]]; then
    which=both
    default=--default
fi

case $which in
    dark) install_dark; uuid=46edc057-d8e6-4aa1-a6a2-3b83272ead24 ;;
    light) install_light; uuid=5c7f0537-5c7f-4f86-8e09-fadd0a973257 ;;
    both) install_dark; install_light; uuid=46edc057-d8e6-4aa1-a6a2-3b83272ead24 ;;
    *) echo "usage: $0 [dark|light|both] [--default]" >&2; exit 1 ;;
esac

if [[ $default == "--default" ]]; then
    gsettings set "$LIST" default "$uuid"
    echo "Set as default profile"
fi
